catch_body_screen.body:
// Original checkShaders:168-209 retries missing groups on the next player tick.
// Do not turn a transient/resource-pack failure into a permanent session latch.
if (chain != null) chain.close(); CHAINS.remove(name); FAILED.put(name, client.player.tickCount);
Thaumcraft.LOG.error("Unable to render warp post chain {}", name, failure);

outputs.addLast(entry.retry(level.getGameTime()));
Thaumcraft.LOG.warn("Crucible output preparation failed at {}; retaining result", entry.source, exception);
continue;

// Preserve WHOLE payload, including any unread item/reference. Root
// retirement must custody that payload before this BE can disappear.
rejected = tag.copy(); fenced = true; pending = null;
// ONE quarantine owner, not decoded slots PLUS duplicate raw rows.
focus = pick = ItemStack.EMPTY; stats = new ArcaneBoreMath.Stats(0, 0, 0);
workReference = null; needsReconciliation = false;
Thaumcraft.LOG.warn("Quarantined malformed bore at {}", worldPosition, malformed);

if (!paid) throw failure;
// A spent pearl never refunds/retries an already applied explosion or a callback-partial effect.
Thaumcraft.LOG.warn("Primordial pearl effects interrupted after payment at {}", pos, failure);
return InteractionResult.CONSUME;

if(!paid)throw failure;
Thaumcraft.LOG.warn("Loot bag publication interrupted after native payment",failure);
return InteractionResultHolder.consume(stack);

if (scope.operation() == BoreOperation.EVACUATE) {
    // Also covers failure before the initial canonical capture. Do
    // not let native onRemove delete an unclaimed physical owner.
    try { retainRetirement(frame, failure.getClass().getName()); }
    catch (RuntimeException | Error retentionFailure) {
        if (retentionFailure != failure) failure.addSuppressed(retentionFailure);
        throw failure;
    }
    if (failure instanceof Error) throw failure;
    Thaumcraft.LOG.warn("Bore retirement retained as unsendable custody at {}", top.getBlockPos(), failure);
    return;
} else if (frame.armed && !frame.witnessed && frame.escrow != null) unknown(frame);
else if (!frame.entered && scope.operation() == BoreOperation.FINISH) {
    try { frame.refuse(); } catch (RuntimeException refused) { failure.addSuppressed(refused); }
}
throw failure;

// No trustworthy outcome, even if a callback already changed the
// target. Fence the paid reservation; never retry/refund/emit it.
unknown(f);
Thaumcraft.LOG.error("Bore removal threw at {}; UNKNOWN reservation retained without output", f.before.targetPos(), failure);
return;

// The true native witness is already durable. An observer
// failure cannot revoke ownership or crash away settlement.
Thaumcraft.LOG.warn("Bore AFTER notification failed after witnessed removal at {}", f.before.targetPos(), notice);

lastSaveFailure = failure.getClass().getName(); queue.setDirty();
// Do NOT substitute an empty diagnostic row. Aborting this save
// leaves actual objects in this queue owner for a coherent retry.
throw failure;

// The bridge validates before its raw clear and performs no fallible
// work after it; preparation failure must not leave a second owner.
data.pending.removeLastOccurrence(entry);
throw failure;

pending.addLast(entry.retryAt(level.getGameTime() + RETRY_DELAY));
setDirty();
Thaumcraft.LOG.warn("Inventory output preparation failed at {}; retaining pending items", entry.source, exception);
continue;

// Native may already have removed the block before an onRemove
// exception. Do not infer success or refund a potentially free extra.
if (attempt.reservation != null) {
    attempt.permit.indeterminate = true;
    Thaumcraft.LOG.warn("Excavation extra reservation retained after exceptional native removal; expansion revoked, no success/drop witness or refund", failure);
}
throw failure;

// The original reads the same labyrinth here; a labyrinth that cannot be read must
// not turn the decoration of a chunk into a server crash. The ring pass of the
// chunk reports the failure itself.
return false;

// Native raw application is callback-free after full preparation.
// A violated exact-change invariant is a bug, not an unpaid retry.
if (mutation.raw) throw failure;
return new Attempt(selected, 0, failure);

// Retirement is irrevocable, including write-then-throw callbacks.
// Never retry an already partially applied explosion/birth operation.
Thaumcraft.LOG.warn("Energized node failure interrupted at {} (never retried after retirement)", source.getBlockPos(), failure);

// Authority/crash correction to ResearchManager:120-134: prepare a
// valid note before spending paper or ink. No player RNG was used.
return rejected(Failure.INVALID_GENERATION, plan.key);

context.phase = Phase.NATIVE_REJECTED;
Thaumcraft.LOG.warn("Golem Use post-hook validation failed at {}; native body refused", context.marker.pos(), failure);
return false;

// Do not clear actual actor stock, repeat a raw handoff, emit another
// copy, or pretend EMPTY when a native preparation invariant fails.
context.workerActive = context.detachStarted && !context.stockSettled;
quarantine(context, "Use ownership/restoration failed; actor retained and no automatic retry", failure);

// A refused or unknown actor never authorizes a pond. This is not a
// universal adapter for addon-specific fishing/claim event systems.
return false;

Thaumcraft.LOG.warn("Golem water drain {} at {}; no repeated grant or post-commit rollback",
        committed ? "committed before feedback failed" : "refused or interrupted", pos, failure);
return committed;

// A callback may already have changed the world. Never restore the
// captured block or replay its drops in response to an exception.
Thaumcraft.LOG.warn("Golem block action refused or interrupted at {}; no synthetic drops or rollback", pos, failure);
return false;

if (!retiring) Thaumcraft.LOG.warn("Golem recall failed at {}; retaining the living entity and cargo", blockPosition(), failure);
else throw failure;
return false;

// Preparation failed, not an invitation to reset malformed data or
// mutate somebody else's stock/entity. Native admission is never undone.
if (golem != null && nativeOwned(golem)) throw failure;
if (golem != null) discardDetached(golem);
Thaumcraft.LOG.warn("Straw golem placement failed; retaining the placer", failure);
return InteractionResult.FAIL;

// The edit is already committed. Return CONSUME, not a retry which
// would toggle the same marker a second time or overwrite callbacks.
Thaumcraft.LOG.warn("Golem bell notification failed at {}", pos, failure);

// Later identity/provider observations are also post-commit call-outs.
// Previously reported actual debits remain actual, never a refund0.
LOG.warn("VisNet frame stopped after {} committed raw vis", actual, failure);
